1	// The task declaration contract (per-project-scheduling DESIGN §1) — the single
2	// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { ACCEPTED_FREQUENCIES, normalizeFrequency } from './calendar.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	import { EXECUTING_LEASH_MS } from './queue/leases.mjs';
10	
11	// A declared timeout is always a whole number of seconds, > 0.
12	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
13	
14	// A code-work command must stay inside its own task directory — no absolute
15	// path and no `..` traversal in the command string — the same containment the
16	// worker-file rule gives agent_instructions (task-code-work DESIGN §2).
17	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
18	
19	// Task execution is two similar, consecutive phases — deterministic CODE-WORK,
20	// then AGENTIC WORK — and the field names say so. Neither phase is named for
21	// the other: the code phase is not preparation for the agent, it is the first
22	// of two peers, and a task may declare only it.
23	//
24	// Two renames have reached these fields (2026-08-06 agent_preprocessing →
25	// prework, 2026-08-18 prework → code-work); both legacy spellings stay accepted
26	// here, since a consumer's own local packs rename on their own clock. Every
27	// legacy key maps straight to today's canonical name rather than to its
28	// immediate successor, so a declaration written for the oldest vocabulary
29	// normalizes in one pass. Canonical names win when both are present.
30	const LEGACY_FIELDS = {
31	  agent_preprocessing: 'code_work',
32	  agent_preprocessing_timeout: 'code_work_timeout',
33	  prework: 'code_work',
34	  prework_timeout: 'code_work_timeout',
35	  after: 'schedule_after',
36	};
37	
38	// Return the declaration with canonical field names. Non-objects pass through
39	// untouched so validateTaskDeclaration still reports them. Loaders (discover,
40	// resolve-dispatch) normalize once; everything downstream sees only `code_work`.
41	export function normalizeTaskDeclaration(decl) {
42	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
43	  const out = { ...decl };
44	  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
45	    if (out[legacy] !== undefined) {
46	      if (out[canonical] === undefined) out[canonical] = out[legacy];
47	      delete out[legacy];
48	    }
49	  }
50	  // THE ONE DOOR for the retired frequency spellings (DESIGN §17.1). Here rather than in the
51	  // calendar because a frequency is read by more than the calendar — see `normalizeFrequency`.
52	  if (out.frequency !== undefined) out.frequency = normalizeFrequency(out.frequency);
53	  return out;
54	}
55	
56	// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
57	// promise: `none` may never open a PR, `open-pr` may open but never merge,
58	// `merged-pr` may arm auto-merge. "No change" is always legal.
59	export const OUTCOMES = ['none', 'open-pr', 'merged-pr'];
60	
61	
62	// The retired scope vocabulary. It routed a slot dispatch to one of two labels, and
63	// its last reader went with the slot scheduler (#974): reach is now a property of
64	// which endpoint the hand-off calls (`invocation_endpoint`), so nothing anywhere
65	// asks a task what its scope is.
66	//
67	// The values stay so a declaration still carrying the field VALIDATES rather than
68	// failing — nothing converges a member's task files, so a member cannot be moved
69	// off it by a release; `task-declaration-shape` raises it as an advisory rename
70	// instead, and the field is dropped as each declaration is next edited.
71	// @deprecated Declares nothing. Name an `invocation_endpoint` if the task needed
72	//   reach an ordinary session in its repo does not have.
73	export const SESSION_SCOPES = ['self', 'fleet'];
74	
75	// What must happen to a task's work item when a recovery path would re-execute it
76	// (tasks-dispatch DESIGN §6). `requeue` is the safe-side default for sweep-shaped
77	// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
78	export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];
79	
80	
81	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
82	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
83	// it) — that restriction is enforced where signals are collected, not here; the
84	// shape check only asserts a declared name is a real collector.
85	export const SIGNAL_NAMES = [
86	  'commits', 'prs', 'issues', 'branches', 'release',
87	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet', 'request',
88	];
89	
90	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
91	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
92	// task itself; the caller supplies the already-loaded default export.
93	export function validateTaskDeclaration(raw) {
94	  const decl = normalizeTaskDeclaration(raw);
95	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
96	    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
97	  }
98	  const problems = [];
99	  const bad = (what, fix) => problems.push({ what, fix });
100	
101	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
102	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
103	  }
104	  // ACCEPTED, not FREQUENCIES: a member's own task file may still carry a retired spelling and
105	  // must keep running, since nothing converges a member's task files. Stopping a NEW declaration
106	  // from naming one is the author-time declaration-shape check's job, not this one's — the split
107	  // is deliberate, and `FREQUENCIES` beside `ACCEPTED_FREQUENCIES` in calendar.mjs is where it is
108	  // spelled out.
109	  if (!ACCEPTED_FREQUENCIES.includes(decl.frequency)) {
110	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${ACCEPTED_FREQUENCIES.join(', ')}`);
111	  }
112	  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
113	    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
114	  }
115	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
116	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
117	  }
118	  if (!OUTCOMES.includes(decl.expected_outcome)) {
119	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
120	  }
121	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
122	  // that's the worker file the agent reads. A `none` task runs no agent, so the
123	  // field is not applicable and is neither required nor validated when present.
124	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
125	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.mjs (e.g. "task.md")');
126	  }
127	  // precondition(signals, config, item). The third argument is THIS occurrence's own
128	  // facts — its `Request`, its `Model`, its `Not-before` — for a verdict that is
129	  // about one target rather than about the repo: a request item's verdict is about
130	  // the issue it names, which no signal bundle can single out. Backwards compatible
131	  // by construction, since a precondition simply does not declare an argument it
132	  // does not read.
133	  //
134	  // Three answers, not two: `{ run: true }`, `{ run: false, reason }`, and
135	  // `{ error }` — the precondition COULD NOT ANSWER. The third is a run failure
136	  // rather than a verdict (F27): a decline is a decision about the world, and one
137	  // taken on an API that would not answer is a guess whose write-backs cannot land.
138	  if (typeof decl.precondition !== 'function') {
139	    bad('"precondition" is not a function', 'export a precondition(signals, config, item) that returns { run, reason, context? } — or { error } when it could not answer');
140	  }
141	
142	  /**
143	   * model_from_request — OPTIONAL, and reserved to the engine's own built-in task.
144	   * A task that declares it runs at the model the ITEM names (`Model:`, written by
145	   * the scheduler run from a write-gated label), falling back to `agent_model` when the item
146	   * names none. It is the only field that lets anything on an item define behaviour,
147	   * so it is fenced rather than waved through (DESIGN §16.7): the shape check accepts
148	   * only `true`, and discovery gives pack tasks no way to be the built-in one.
149	   */
150	  if (decl.model_from_request !== undefined && decl.model_from_request !== true) {
151	    bad(`"model_from_request" ${JSON.stringify(decl.model_from_request)} is not \`true\``,
152	      'drop the field — only the engine\'s built-in request task reads a model off its item, and every other task names its own agent_model');
153	  }
154	
155	  /**
156	   * session_scope — OPTIONAL, and READ BY NOTHING. Kept validated rather than
157	   * rejected outright so a lingering declaration still loads: nothing carries a
158	   * task-file change across the fleet, so a member cannot be migrated off the field
159	   * by a release, and rejecting it would stop that member's task running over a word
160	   * that no longer does anything.
161	   * @deprecated Declares nothing since #974. Drop it; if the task needed reach an
162	   *   ordinary session in its repo does not have, name an `invocation_endpoint`.
163	   */
164	  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
165	    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `drop it — the field is read by nothing; name an "invocation_endpoint" if the task needs wider reach`);
166	  }
167	
168	  // Code-work (task-code-work DESIGN §2) — OPTIONAL. The deterministic first phase
169	  // of task execution, a command the scheduler runs as a subprocess. When present
170	  // it must be a non-empty, task-local command AND carry a positive-integer
171	  // code_work_timeout — the hard kill that bounds the subprocess.
172	  if (decl.code_work !== undefined) {
173	    if (typeof decl.code_work !== 'string' || decl.code_work.trim() === '') {
174	      bad('"code_work" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.mjs, e.g. "node prepare.mjs"');
175	    } else if (escapesTaskDir(decl.code_work)) {
176	      bad('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
177	    }
178	    if (!isPositiveInt(decl.code_work_timeout)) {
179	      bad('"code_work" is set but "code_work_timeout" is not a positive integer', 'add "code_work_timeout": the seconds after which the subprocess is killed and the task fails');
180	    } else if (decl.code_work_timeout * 1000 >= EXECUTING_LEASH_MS) {
181	      // F17: a code-work legally allowed to outlive the executing leash is reclaimed
182	      // WHILE ALIVE, and the failure is not one duplicate run but a livelock —
183	      // every tenure reclaimed before it can finish, code-work re-executing each
184	      // cycle, the occurrence never converging. The leash is the engine's, so the
185	      // comparison is made where a declaration is judged.
186	      bad(`"code_work_timeout" (${decl.code_work_timeout}s) reaches the executor's ${EXECUTING_LEASH_MS / 60e3}-minute claim leash`,
187	        `bound code_work under ${EXECUTING_LEASH_MS / 60e3} minutes — a code_work that can outlive the leash is reclaimed while still running, and the item livelocks`);
188	    }
189	  }
190	
191	  // --- the work-item queue's three optional declarations (tasks-dispatch DESIGN) ---
192	
193	  // `schedule_after` — ordering, declared (DESIGN §9). A list of `<pack>/<task>` ids this
194	  // task yields to WHILE THEY ARE LIVE THIS CYCLE. It compiles to the executor's
195	  // pick-time yield, never to a `Blocked-by` edge: a standing item that rolls
196	  // never closes, so blocked-by would starve every dependent of a quiet upstream
197	  // forever. The engine never learns what any named task does — it reads item
198	  // states, generically.
199	  if (decl.schedule_after !== undefined
200	      && !(Array.isArray(decl.schedule_after)
201	        && decl.schedule_after.every((s) => typeof s === 'string' && /^[^/\s]+\/[^/\s]+$/.test(s)))) {
202	    bad('"schedule_after" is not an array of "<pack>/<task>" ids', 'e.g. "schedule_after": ["claudinite-lifecycle/update"] — this task is not scheduled onto an executor while those are live this cycle');
203	  }
204	
205	  // `on_interrupt` — the ack-early/ack-late dial (DESIGN §6). Most of this fleet's
206	  // tasks are sweep-shaped and converge safely on a re-run, so the default is
207	  // `requeue`. A genuinely one-shot side effect (a store submission, an external
208	  // notification) declares `needs-human`, and every recovery path that would
209	  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
210	  // instead: at-most-once plus a human.
211	  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
212	    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
213	  }
214	
215	  // `invocation_endpoint` — a NAME, never a URL (DESIGN §12). The repo's config
216	  // maps the name to the URL and to the name of the Actions secret holding its
217	  // token, so no vendored pack file carries deployment detail or anything adjacent
218	  // to a credential. This is also what replaces session_scope: reach is a property
219	  // of which endpoint a task names.
220	  if (decl.invocation_endpoint !== undefined
221	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
222	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
223	  }
224	
225	  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
226	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
227	  // (adoption interactively, the scheduler by owner issue), not to gate anything
228	  // here. So the only shape asserted is "a list of names"; whether the repo has
229	  // actually configured them is a fact about the repo, answered where the secrets
230	  // bundle is readable, never at author time.
231	  if (decl.required_secrets !== undefined
232	      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
233	    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
234	  }
235	
236	  // Execution bound (task-code-work DESIGN §2, §6) — an agentic task MUST
237	  // declare a positive-integer agent_execution_timeout. There is always a bound
238	  // on an agentic run; enforcement is best-effort (the executor surfaces the
239	  // value to the subagent). A `none` task runs no agent, so it needs none.
240	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
241	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
242	  }
243	
244	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
245	  // code-work — a `none` task with no code-work does nothing (DESIGN §4, retiring
246	  // the in-process inline path). Require the command.
247	  if (decl.agent_model === 'none' && decl.code_work === undefined) {
248	    bad('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
249	  }
250	
251	  return problems;
252	}
