import { dirname, join, normalize } from 'node:path';
import { humanTurns, assistantTextAfter, classificationLine, classesIn } from './session-transcript.mjs';
import { addedLines } from './line-scanning.mjs';
import { extractLinks } from './markdown.mjs';

// The fluent check-the-work surface over ctx. Every accessor is null-safe — no
// transcript, no merge-base, an empty branch all yield empty results — so a rule
// reads as one chain with no guard ladders. Mechanism only: a rule still owns
// its patterns, file filters, and failure text.
//
// A rule declaring `scope: 'work'` receives this object as its `run` argument
// (runRule dispatches); check-the-world rules keep the raw ctx until a fluent
// world object exists. The raw surface a work rule still needs (files, read,
// exists, …) is delegated here, so a work rule — and the structural helpers it
// calls, e.g. findExtensionManifest — never touches ctx itself.
export const work = (ctx) => new Work(ctx);

// The single dispatch seam: the runner and every rule test invoke rules through
// this, so a rule's scope decides its context in exactly one place. Extra args
// pass through (some rules take test-only options after the context).
export const runRule = (rule, ctx, ...args) => rule.run(rule.scope === 'work' ? work(ctx) : ctx, ...args);

// Null-object for "no such turn": every accessor answers emptily, so a chain
// ending in .last() never needs an existence guard before its predicates.
const NO_TURN = {
  exists: false, text: '', timestamp: null,
  excerpt: () => '', reply: () => '', classified: () => false,
  classes: () => new Set(), time: () => 0,
};

class Turn {
  constructor(entries, { index, timestamp, text }) {
    this.entries = entries;
    this.index = index;
    this.timestamp = timestamp;
    this.text = text;
    this.exists = true;
  }

  excerpt(n) { return this.text.replace(/\s+/g, ' ').slice(0, n); }
  reply() { return assistantTextAfter(this.entries, this.index); }
  classified() { return classificationLine(this.reply()) !== null; }
  classes() { return classesIn(classificationLine(this.reply())); }
  time() { return Date.parse(this.timestamp ?? '') || 0; }
}

// Array subclass so filter/map stay chainable and .last() survives them.
class Turns extends Array {
  last() { return this.length ? this[this.length - 1] : NO_TURN; }
}

class Conversation {
  constructor(entries) { this.entries = entries ?? []; }

  ownerTurns() {
    const turns = new Turns();
    for (const t of humanTurns(this.entries)) turns.push(new Turn(this.entries, t));
    return turns;
  }
}

class Work {
  constructor(ctx) { this.ctx = ctx; }

  get branch() { return this.ctx.branch; }
  get baseRef() { return this.ctx.baseRef; }
  get commits() { return this.ctx.commits; }
  get files() { return this.ctx.files; }
  get changedFiles() { return this.ctx.changedFiles; }
  get deleted() { return this.ctx.deleted; }
  get tracked() { return this.ctx.tracked; }
  // The discovered pack objects (runner-attached) and the normalized config —
  // the pair a rule that reasons over pack metadata (e.g. adoption-interview
  // state) hands to the interview helpers, without reaching into ctx itself.
  get packs() { return this.ctx.packs ?? []; }
  get config() { return this.ctx.config; }
  read(path) { return this.ctx.read(path); }
  readBase(path) { return this.ctx.readBase(path); }
  exists(path) { return this.ctx.exists(path); }
  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }

  conversation() { return new Conversation(this.ctx.conversation()); }

  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }

  onDefaultBranch() { return this.ctx.branch === 'main' || this.ctx.branch === 'master'; }

  introducedMerges() { return this.ctx.introducedMergeCommits(); }

  // Branch commits since the merge-base, oldest first, each with a parsed .time.
  branchCommits() {
    return this.ctx.commitsWithFiles().map((c) => ({ ...c, time: Date.parse(c.date) || 0 }));
  }

  // `file` parsed as JSON at head and at the scoping base; a side that is
  // absent or unparsable is null, so set-vs-base rules need no try/catch.
  jsonPair(file) {
    const parse = (text) => {
      if (text === null) return null;
      try { return JSON.parse(text); } catch { return null; }
    };
    return { head: parse(this.ctx.read(file)), base: parse(this.ctx.readBase(file)) };
  }

  filesContaining(needle, files = this.ctx.files) {
    return files.filter((f) => (this.ctx.read(f) ?? '').includes(needle));
  }

  // Relative Markdown links that resolve to nothing: [{ file, line, target, resolved }].
  // Links reaching outside the repo aren't verifiable here and are skipped.
  deadLinks(files) {
    const out = [];
    for (const file of (files ?? this.ctx.files).filter((f) => f.endsWith('.md'))) {
      const text = this.ctx.read(file);
      if (text === null) continue;
      for (const { target, line } of extractLinks(text)) {
        const resolved = normalize(join(dirname(file), target));
        if (resolved.startsWith('..') || this.ctx.exists(resolved)) continue;
        out.push({ file, line, target, resolved });
      }
    }
    return out;
  }

  // Tracked lines still naming a path this change deletes: [{ file, line, text, gone }].
  // A hit whose every occurrence widens to a path token that still resolves is a
  // rename that kept the basename, not a dangling reference — dropped. `tolerated(gone)`
  // lets the rule exempt paths something else deliberately governs.
  danglingReferences(tolerated = () => false) {
    const out = [];
    for (const gone of this.ctx.deleted) {
      if (tolerated(gone)) continue;
      for (const hit of this.ctx.grepTracked(gone)) {
        if (hit.file === gone || referencesSurvivingPath(hit, gone, this.ctx)) continue;
        out.push({ ...hit, gone });
      }
    }
    return out;
  }
}

const PATH_CHAR = /[\w./@-]/;

function widenToken(text, start, end) {
  let s = start;
  let e = end;
  while (s > 0 && PATH_CHAR.test(text[s - 1])) s--;
  while (e < text.length && PATH_CHAR.test(text[e])) e++;
  return text.slice(s, e);
}

function referencesSurvivingPath(hit, gone, ctx) {
  let idx = hit.text.indexOf(gone);
  if (idx === -1) return false;
  while (idx !== -1) {
    const token = widenToken(hit.text, idx, idx + gone.length);
    const resolved = normalize(join(dirname(hit.file), token));
    if (!((token !== gone && ctx.exists(token)) || ctx.exists(resolved))) return false;
    idx = hit.text.indexOf(gone, idx + 1);
  }
  return true;
}

import { basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';

// The write-surface gate for the improve-comments pass. Its skill bounds every edit
// to comments in code files and to `README.md` documents; the pass runs unattended
// and writes the repo's OWN SOURCE — the one surface no other tidy-repo task
// touches — so the boundary needs a machine guarantee rather than a prose request.
//
// THE PERMISSION IS READ, NEVER ASSERTED. A file passes because its code is
// identical once the comments are stripped from both sides, not because the run
// says it only touched comments. That is the whole point: a run that quietly
// renamed a variable while "improving comments" is exactly what this catches, and
// a run cannot talk its way past a text comparison.
//
// THREE SHAPES FAIL, and each is deliberate rather than an oversight:
//   - a file whose language `commentOnly` cannot parse counts as code, so a comment
//     edit in one reds the run. Answering "I could not look" as a pass would make
//     the gate silently narrower than the languages a repo actually holds;
//   - an ADDED or DELETED code file is never comment-only, whatever it holds — a
//     whole file is a whole file, and this pass does not add or remove them;
//   - a DELETED `README.md` is not an improvement to a README. Modifying one is the
//     pass's business; deciding a document should not exist is not;
//   - ANY change under `.claudinite/`, comment-only or not. The mount is not the
//     repo's own source: `shared/` is vendored and the next converge replaces it
//     whole (that half is already invisible to every check — repo-context drops
//     the shared prefix), and `.claudinite/local/` is what the growth tasks write.
//     The task's precondition keeps the mount out of a round's scope; this is what
//     holds when a run reaches for one anyway.
//
// RELEVANCE IS THE PINNED COMMIT SUBJECT, the same self-gating shape
// claudinite-growth's capture gate uses: the run marks itself, so this rule can run
// everywhere tidy-repo is active — at the session Stop hook and on every PR — and
// costs ~nothing on a branch that is not this pass.
export const IMPROVE_COMMENTS_RUN = /^Claudinite tidy: improve comments/;

const isReadme = (p) => basename(p).toLowerCase() === 'readme.md';

// The same prefix the task's precondition filters its scope by (MOUNT_PREFIX in
// tasks/improve-comments/task.mjs); that task imports nothing, so the two are held
// in step by the test beside this check rather than by a shared constant.
const MOUNT_PREFIX = '.claudinite/';
const inMount = (p) => p.startsWith(MOUNT_PREFIX);

const rule = {
  id: 'improve-comments-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/tidy-repo/skills/improve-comments/SKILL.md',
  description: 'An improve-comments run changes only comments in code files outside the .claudinite/ mount, and README.md documents',
  why: 'the pass runs unattended against the repo\'s own source, and its whole safety case is that a comment cannot change behaviour — a run that also moved a line has made an unreviewed code change wearing a housekeeping title',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => IMPROVE_COMMENTS_RUN.test(m))) return [];

    const deleted = new Set(work.deleted);
    return [...new Set([...work.changedFiles, ...work.deleted])]
      .filter((p) => inMount(p) || (isReadme(p) ? deleted.has(p) : !commentOnly(p, work.readBase(p), work.read(p))))
      .sort()
      .map((p) => finding(rule, inMount(p)
        ? {
          file: p,
          what: `an improve-comments run changed ${p}, which is inside the ${MOUNT_PREFIX} mount`,
          fix: `revert ${p} — the mount is not this repo's source: the next converge replaces it whole, so a comment improved there is gone by morning; take the change to the canon instead`,
        }
        : isReadme(p)
        ? {
          file: p,
          what: `an improve-comments run deleted ${p} — a README may be improved, never removed`,
          fix: 'restore the file; deciding a document should not exist is a change that gets reviewed, not a comment pass',
        }
        : unparseable(p)
          ? {
            file: p,
            what: `an improve-comments run changed ${p}, whose language the comment parser cannot read`,
            fix: `revert ${p} — outside the parser's set a file counts as code, so nothing here can show the change was only comments; leave them to a change that gets reviewed`,
          }
          : {
            file: p,
            what: work.readBase(p) === null || deleted.has(p)
              ? `an improve-comments run added or deleted ${p}, which is never a comment-only change`
              : `an improve-comments run changed more than the comments in ${p}`,
            fix: 'keep the branch to comment text in code files and to README.md content — a rename, a moved line or a reformat is its own change, with its own review',
          }));
  },
};

// Whether the file's language is one `commentOnly` can parse at all. Only used to
// pick the remedy: a run told "you changed more than comments" about a `.py` file
// it only commented would go looking for a code edit that isn't there.
function unparseable(p) {
  const dot = p.lastIndexOf('.');
  return !COMMENT_CHECKABLE.has(dot === -1 ? '' : p.slice(dot).toLowerCase());
}

export default [rule];

