+    assert.ok(rules.has('alpha-docs'));
+    assert.ok(!rules.has('beta-docs'), 'an undeclared pack contributes no merge rules');
+    assert.ok(errors.some((e) => /doc-changes.*already taken/.test(e)), 'shadowing a built-in is an error');
+  } finally {
