15	  for (const f of MODEL_FAMILIES) assert.equal(resolveModel(f), MODEL_MAP[f]);
16	  assert.equal(resolveModel('none'), null);
17	  assert.equal(isAgentless('none'), true);
18	  assert.equal(isAgentless('opus'), false);
19	  assert.throws(() => resolveModel('gpt'), /unknown model family/);
20	});
