22	// --- task-contract ---
23	const validTask = {
24	  id: 'growth-extract',
25	  frequency: 'daily',
26	  precondition_signals: ['commits', 'prs', 'issues'],
27	  agent_model: 'opus',
28	  expected_outcome: 'merged-pr',
29	  agent_instructions: 'task.md',
30	  agent_execution_timeout: 1800,
31	  precondition() { return { run: true, reason: 'x' }; },
32	};
33	
34	test('validateTaskDeclaration accepts a well-formed declaration', () => {
35	  assert.deepEqual(validateTaskDeclaration(validTask), []);
36	});
37	
38	test('validateTaskDeclaration: session_scope is optional, defaults valid, and rejects a bad value', () => {
39	  assert.deepEqual(validateTaskDeclaration(validTask), []);                                  // omitted → fine (defaults to self)
40	  assert.deepEqual(validateTaskDeclaration({ ...validTask, session_scope: 'self' }), []);
41	  assert.deepEqual(validateTaskDeclaration({ ...validTask, session_scope: 'fleet' }), []);
42	  assert.match(validateTaskDeclaration({ ...validTask, session_scope: 'global' })[0].what, /not a legal session scope/);
43	});
