45	test('validateTaskDeclaration requires agent_execution_timeout on an agentic task', () => {
46	  const { agent_execution_timeout, ...noBound } = validTask;
47	  assert.match(validateTaskDeclaration(noBound)[0].what, /no positive-integer "agent_execution_timeout"/);
48	  // a non-integer or non-positive bound is equally rejected
