1	// Executor-side deterministic validation of a dispatch issue, BEFORE any model
2	// judgment (per-project-scheduling DESIGN §5.2). Given the issue body, it asserts
3	// in code that the first line is a legal task path, the task file exists at HEAD,
4	// its pack is declared, and its `task.mjs` sibling parses to a well-formed
5	// declaration — then resolves the model and outcome ceiling the executor will
6	// enforce. An invalid dispatch is rejected (the executor de-labels it and
7	// converges it to needs-human), so a forged or mangled issue never runs.
8	//
9	// Pure over injected capabilities so it unit-tests without a repo or GitHub. It
10	// is NOT a CLI — the executor shell beside it, `resolve-dispatch.mjs`, is what
11	// drives it in production: that shell takes the issue body out of the label
12	// event's payload on disk and wires `exists`/`isPackDeclared`/`loadTask` to the
13	// checkout, so validating a dispatch costs no GitHub call at all.
14	
15	import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';
16	import { resolveModel } from './model-map.mjs';
17	import { BUILT_IN_PACK, BUILT_IN_PATH_RE } from './built-in-tasks.mjs';
18	import { parseWorkItemBody } from './queue/work-item.mjs';
19	
20	// The only shape a dispatch first line may take (DESIGN §5.2). Anchored end to
21	// end — no query strings, no trailing junk, exactly one pack and one task
22	// segment under a packs/ root. The `.claudinite/(shared|local)/` prefix is
23	// OPTIONAL: a consumer's task path carries it (its canon is mounted at
24	// `.claudinite/shared/packs/`, its own packs at `.claudinite/local/packs/`),
25	// while the CANON repo runs its own tree and dispatches root-relative paths
26	// (`packs/<pack>/…` for its canon packs, `.claudinite/local/packs/<pack>/…` for
27	// its local packs). All three forms are legal; nothing else is.
28	export const DISPATCH_PATH_RE = /^(?:\.claudinite\/(?:shared|local)\/)?packs\/([^/]+)\/tasks\/([^/]+)\/task\.md$/;
29	
30	// The task path a dispatch body points at — its first line, trimmed.
31	export const dispatchFirstLine = (body) => String(body ?? '').split('\n')[0].trim();
32	
33	const reject = (reason, extra = {}) => ({ ok: false, reason, ...extra });
34	
35	// Validate a dispatch body. Capabilities (all injected for testability):
36	//   exists(path)        -> boolean   — does this repo-relative path exist at HEAD
37	//   isPackDeclared(id)  -> boolean   — is this pack active in .claudinite-settings.json
38	//   loadTask(mjsPath)   -> decl      — load the task.mjs default export (throws on parse error)
39	// Returns { ok:true, pack, task, taskPath, model, resolvedModel, outcome },
40	// { ok:false, gone:true, pack, task, reason } — a well-formed dispatch whose task
41	// the repo NO LONGER CARRIES (file gone, sibling gone, pack undeclared): the
42	// executor CLOSES the issue as obsolete (owner, 2026-08-06) rather than parking
43	// it on needs-human, because a task that was removed or deactivated is not an
44	// anomaly a human needs to triage — or { ok:false, reason } for a genuinely
45	// malformed dispatch (bad path shape, unparseable declaration), which stays a
46	// needs-human convergence since it may be forgery or a broken task.
47	export function validateDispatchBody(body, { exists, isPackDeclared, loadTask }) {
48	  const firstLine = dispatchFirstLine(body);
49	  // Two legal shapes: a pack task, and the engine's own built-in root (DESIGN
50	  // §16.2). The built-in one is not a pack and is never declared — wherever the
51	  // queue runs it is active — so it skips the declaration check rather than failing
52	  // it, and nothing else about validation differs.
