1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { makeRepo, cleanup } from '../../../engine-tests/helpers.mjs';
4	import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
5	import rule from '../worldRules/task-declaration-shape.mjs';
6	
7	const goodTask = `export default {
8	  id: 'growth-extract',
9	  frequency: 'daily',
10	  precondition_signals: ['commits', 'prs'],
11	  agent_model: 'opus',
12	  expected_outcome: 'merged-pr',
13	  agent_instructions: 'task.md',
14	  agent_execution_timeout: 1800,
15	  precondition(signals, config) { return { run: false }; },
16	};
17	`;
18	const TASK = '.claudinite/local/packs/mypack/tasks/growth-extract/task.mjs';
19	
20	const run = (files) => {
21	  const root = makeRepo({ changed: files });
22	  try { return rule.run(buildContext({ root, mode: 'all' })); } finally { cleanup(root); }
23	};
24	
25	test('task-declaration-shape: a well-formed task.mjs yields no findings', () => {
26	  assert.deepEqual(run({ [TASK]: goodTask }), []);
27	});
28	
29	test('task-declaration-shape: is inert when no task.mjs exists', () => {
30	  assert.deepEqual(run({ 'src/app.js': 'x\n' }), []);
31	});
32	
33	test('task-declaration-shape: flags illegal enum values', () => {
34	  const bad = goodTask
35	    .replace("frequency: 'daily'", "frequency: 'nightly'")
36	    .replace("agent_model: 'opus'", "agent_model: 'gpt'")
37	    .replace("expected_outcome: 'merged-pr'", "expected_outcome: 'push'");
38	  const whats = run({ [TASK]: bad }).map((f) => f.what).join(' | ');
39	  assert.match(whats, /"frequency" is "nightly", not a legal value/);
40	  assert.match(whats, /"agent_model" is "gpt", not a legal value/);
41	  assert.match(whats, /"expected_outcome" is "push", not a legal value/);
42	});
43	
44	// The strict half of the frequency door (tasks-dispatch DESIGN §17.1). The RUNTIME accepts a
45	// retired spelling forever, because a member's task file is its own data and no vendoring pass
46	// rewrites it — so the only thing standing between the corpus and a new declaration on the dead
47	// vocabulary is this author-time check, which runs in the canon.
48	test('task-declaration-shape: the retired frequency spellings cannot be written anew', () => {
49	  for (const retired of ['hourly', 'daily-2h', 'daily-1h', 'daily+1h']) {
50	    const bad = goodTask.replace("frequency: 'daily'", `frequency: '${retired}'`);
51	    const findings = run({ [TASK]: bad });
52	    const whats = findings.map((f) => f.what).join(' | ');
53	    assert.match(whats, new RegExp(`"frequency" is "${retired.replace('+', '\\+')}", not a legal value`),
54	      `${retired} is rejected at author time`);
55	    assert.ok(findings.some((f) => f.severity === 'blocking'), `${retired} blocks, not advises`);
56	    // …and the remedy names only the surviving vocabulary.
57	    assert.match(findings.find((f) => f.what.includes('frequency')).fix, /use one of: daily, weekly, monthly, manual/);
58	  }
59	});
60	
61	// The ordering field's rename. ADVISORY, not blocking: the runtime normalizes `after` at the
62	// door forever, so a member's own task file keeps its ordering and its CI must not go red over a
63	// declaration nobody has edited. The finding is what drives the fleet to the canonical spelling.
64	test('task-declaration-shape: the legacy `after` ordering field is an advisory rename', () => {
65	  const legacy = goodTask.replace("  frequency: 'daily',",
66	    "  frequency: 'daily',\n  after: ['claudinite-lifecycle/update'],");
67	  const f = run({ [TASK]: legacy });
68	  assert.equal(f.length, 1);
69	  assert.equal(f[0].severity, 'advisory', 'never blocking — the runtime still honours it');
70	  assert.match(f[0].what, /legacy name "after"/);
71	  assert.match(f[0].fix, /rename "after" to "schedule_after"/);
72	});
73	
74	test('task-declaration-shape: the canonical `schedule_after` is clean', () => {
75	  const canonical = goodTask.replace("  frequency: 'daily',",
76	    "  frequency: 'daily',\n  schedule_after: ['claudinite-lifecycle/update'],");
77	  assert.deepEqual(run({ [TASK]: canonical }), [],
78	    'the canonical spelling must not match the legacy pattern on its own tail');
79	});
80	
81	test('task-declaration-shape: flags missing required fields', () => {
82	  const bad = `export default {
83	  frequency: 'daily',
84	  agent_model: 'sonnet',
85	  expected_outcome: 'none',
86	};
87	`;
88	  const whats = run({ [TASK]: bad }).map((f) => f.what).join(' | ');
