1	import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
2	
3	// Phase 4 of #593: the rule that stops the class recurring by omission.
4	//
5	// `consumer-safe-changes.md` has always SAID that a change to a vendored
6	// contract must carry consumers across it. Nothing enforced that, and #555
7	// merged green while eleven consumer packs stopped validating — because the
8	// canon's own packs were updated in the same commit, and canon CI has nothing
9	// else to look at.
10	//
11	// So this is a check over the canon's OWN diff, not prose about the diff. It
12	// runs in the WORK scope: the branch's change is exactly what it judges, and
13	// judging the whole tree would be meaningless (the tree always contains a
14	// manifest field; the question is whether THIS change added one).
15	//
16	// WHAT IT CATCHES. A change that alters a contract every consumer holds a copy
17	// of, without either of the two things that carry consumers across:
18	//
19	//   a MIGRATION RECORD  — <flow>/migrations/<date>-<name>/migration.mjs, the
20	//                         mechanism that rewrites a member on its next converge
21	//   a REHEARSAL FIXTURE — vendoring/rehearsal/fixtures.mjs, which proves a
22	//                         consumer in that shape still converges green
23	//
24	// Either satisfies it. They answer different questions — "members are moved
25	// across" versus "members are unharmed" — and both are legitimate; a change that
26	// is genuinely additive needs only the second.
27	//
28	// DELIBERATELY NARROW. It triggers on three surfaces, each chosen because a
29	// consumer holds a copy of it and cannot be asked to change in the same commit:
30	//
31	//   pack-schema.mjs        the manifest vocabulary — #555's exact surface
32	//   a rule's `severity`    advisory -> blocking turns a member red overnight
33	//   either workflow stub   every member vendors it verbatim
34	//
35	// It does NOT fire on ordinary pack or engine edits. A rule that cried wolf on
36	// every canon commit would be turned off within a week, and then it would be
37	// worth nothing on the day it mattered.
38	const SCHEMA = 'engine/pack_loader/pack-schema.mjs';
39	// BOTH stubs: a member vendors the executor's workflow as verbatim as the
40	// scheduler's, and its event trigger names label strings literally — the surface a
41	// vocabulary change has to carry members across (#1119).
42	const STUBS = [
43	  'packs/claudinite-tasks/stubs/claudinite-scheduler.yml',
44	  'packs/claudinite-tasks/stubs/claudinite-executor.yml',
45	];
46	// A record folder, not the machinery beside it: registry/apply edits are engine
47	// work and carry no member across anything. A record lives under the flow that
48	// owns it — the engine's own, or one pack's — so both homes count (#768).
49	const MIGRATION_RECORD = /^(engine|packs\/[^/]+)\/migrations\/\d{4}-\d{2}-\d{2}-[^/]+\//;
50	const MIGRATIONS = '<engine|packs/*>/migrations/<date>-<name>/';
51	const FIXTURES = 'vendoring/rehearsal/fixtures.mjs';
52	// The canon's own local packs — repo-only content, outside every vendor set.
53	const LOCAL_PACKS = '.claudinite/local/packs';
54	
55	// A stub's comments are inert: a member vendors them verbatim and no engine reads
56	// them, so rewriting one carries nobody anywhere and asking for a migration record
57	// would be the cried-wolf firing this rule is narrowed to avoid. Both sides must be
58	// readable to reach that conclusion — an unreadable stub stays a contract surface,
59	// so the fail-safe answer is the one a missing file gets.
60	//
61	// `#` only opens a comment at line start or after whitespace, which is what keeps a
62	// `#` inside a YAML scalar (a URL fragment, an `echo 'a # b'`) a real character.
63	function stripYamlComments(text) {
64	  return text.split('\n').map((line) => {
65	    let quote = null;
66	    for (let i = 0; i < line.length; i += 1) {
67	      const c = line[i];
68	      if (quote) { if (c === quote) quote = null; continue; }
69	      if (c === '"' || c === "'") { quote = c; continue; }
70	      if (c === '#' && (i === 0 || /\s/.test(line[i - 1]))) return line.slice(0, i);
71	    }
72	    return line;
73	  }).map((line) => line.trimEnd()).filter(Boolean).join('\n');
74	}
75	
76	function commentOnly(head, base) {
77	  if (typeof head !== 'string' || typeof base !== 'string') return false;
78	  return stripYamlComments(head) === stripYamlComments(base);
79	}
80	
81	// The contract surfaces this change touched, and why each counts. Pure over the
82	// changed-file list plus a head and a base reader, so the whole decision is
83	// testable with no git.
84	export function contractChanges(changed, read, readBase = () => null) {
85	  const out = [];
86	  if (changed.includes(SCHEMA)) {
87	    out.push({ file: SCHEMA, what: 'the pack manifest vocabulary — every consumer local pack is validated against it' });
88	  }
89	  for (const stub of STUBS) {
90	    if (changed.includes(stub) && !commentOnly(read(stub), readBase(stub))) {
91	      out.push({ file: stub, what: 'a workflow stub — every member vendors it verbatim' });
92	    }
93	  }
94	  for (const file of changed) {
95	    // A rule module that BECAME blocking in this change — either newly added, or
96	    // promoted from advisory. That transition is the one that turns a green member
97	    // red without the member changing at all. A rule already blocking at the base
98	    // asked nothing new of anyone, so editing its wording, its `doc` pointer or its
99	    // logic is an ordinary pack edit and stays out of scope: firing on those would
100	    // make every touch of a blocking rule a migration question, which is the
101	    // cried-wolf failure this rule is built to avoid.
102	    if (!/\.mjs$/.test(file) || /\.test\.mjs$/.test(file) || file.startsWith('engine-tests/')) continue;
103	    // A rule in the canon's OWN local packs reaches no consumer by construction:
104	    // the vendor set carries engine/ and packs/, never .claudinite/local/, so such a
105	    // rule runs in exactly one repo — this one — and its severity asks nothing of
106	    // anybody else. Firing here would demand a migration for a change no member can
107	    // even see, which is the cried-wolf failure the narrowing above exists to avoid.
108	    if (file.startsWith(`${LOCAL_PACKS}/`)) continue;
109	    const isBlockingRule = (text) => Boolean(text)
110	      && /severity:\s*'blocking'/.test(text)
111	      && /^\s*const rule = \{/m.test(text);
112	    if (isBlockingRule(read(file)) && !isBlockingRule(readBase(file))) {
113	      out.push({ file, what: 'a rule that became blocking — a severity a member did not ask for turns it red overnight' });
114	    }
115	  }
116	  return out;
117	}
118	
119	// Did this change ALSO carry consumers across? Either answer is enough.
120	export function carriesConsumers(changed) {
121	  return {
122	    migration: changed.some((f) => MIGRATION_RECORD.test(f)),
123	    fixture: changed.includes(FIXTURES),
124	  };
125	}
126	
127	const rule = {
128	  id: 'consumer-safe-change',
129	  severity: 'blocking',
130	  scope: 'work',
131	  description: 'A change to a contract consumers hold a copy of ships a migration record or a rehearsal fixture',
132	  doc: 'consumer-safe-changes.md',
133	  why: 'canon CI cannot see a consumer — the canon\'s own packs are always already migrated, so a change that breaks every member passes it green (#555 did exactly that)',
134	
135	  run(work) {
136	    const changed = work.changedFiles ?? [];
137	    if (!changed.length) return [];
138	    const touched = contractChanges(changed, (f) => work.read(f), (f) => work.readBase(f));
139	    if (!touched.length) return [];
140	    const carried = carriesConsumers(changed);
141	    if (carried.migration || carried.fixture) return [];
142	
143	    const first = touched[0];
144	    return [finding(rule, {
145	      file: first.file,
146	      what: `this change touches ${first.what}, but carries no migration record and no rehearsal fixture`,
147	      fix: `add a record under ${MIGRATIONS} that moves members across, OR a shape in ${FIXTURES} that proves a consumer `
148	        + 'still converges green — then say in the PR which one you chose and why. If the change is genuinely additive, '
149	        + 'the fixture is the honest answer; if it renames or requires something, only a record will move the fleet.',
150	    })];
151	  },
152	};
153	
154	export default rule;
155

