39	// Return the declaration with canonical field names. Non-objects pass through
40	// untouched so validateTaskDeclaration still reports them. Loaders (discover,
41	// resolve-dispatch) normalize once; everything downstream sees only `code_work`.
42	export function normalizeTaskDeclaration(decl) {
43	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
44	  const out = { ...decl };
45	  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
46	    if (out[legacy] !== undefined) {
47	      if (out[canonical] === undefined) out[canonical] = out[legacy];
48	      delete out[legacy];
49	    }
50	  }
51	  // THE ONE DOOR for the retired frequency spellings (DESIGN §17.1). Here rather than in the
52	  // calendar because a frequency is read by more than the calendar — see `normalizeFrequency`.
53	  if (out.frequency !== undefined) out.frequency = normalizeFrequency(out.frequency);
54	  // The retired outcome ceilings become the outcome/policy pair. An explicit
55	  // `automerge` beside a legacy spelling wins: a half-migrated declaration
56	  // keeps the narrower intent it states.
57	  if (LEGACY_OUTCOMES[out.expected_outcome] !== undefined) {
58	    if (out.automerge === undefined) out.automerge = LEGACY_OUTCOMES[out.expected_outcome];
59	    out.expected_outcome = 'pr';
60	  }
61	  return out;
62	}
