+// --- entry builders -----------------------------------------------------------
+
+const added = (file, after = 'x\n') => ({ file, before: null, after });
+const deleted = (file, before = 'x\n') => ({ file, before, after: null });
+const edited = (file, before, after) => ({ file, before, after });
