1	// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
2	// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
3	// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
4	// task that opened a PR — or a task that merged one with nothing authorized —
5	// fails the run and converges to needs-human. "No change" is always legal.
6	//
7	// This seam judges LANE-LEVEL facts only (did the run open, did it merge). A
8	// granular `automerge` policy permits the merge here; whether the actual
9	// diff sat inside the policy is the policy engine's verdict (merge-policy.mjs),
10	// made where the tree is readable — the landing lane's CLI and the
11	// automerge-policy-scope work check.
12	//
13	// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
14	// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
15	// what the task did to PULL REQUESTS.
16	
17	import { OUTCOMES, LEGACY_OUTCOMES } from './task-contract.mjs';
18	import { normalizePolicy } from './merge-policy.mjs';
19	
20	// Verify what a task actually did against its declared ceiling.
21	//   outcome      — the declared ceiling ('none' | 'pr'; the legacy 'open-pr' /
22	//                  'merged-pr' are judged as the pair they normalize to, so a
23	//                  fielded caller passing a raw declaration stays correct)
24	//   automerge — the declared merge policy; absent reads as 'nothing', and an
25	//                  unparsable one the same — a permission that cannot be read
26	//                  was never granted
27	//   openedPr     — did the run open a pull request?
28	//   mergedPr     — did the run merge (or arm auto-merge on) a pull request?
29	// Returns { ok, violation } — violation is null when within the ceiling.
30	export function verifyOutcome({ outcome, automerge, openedPr = false, mergedPr = false }) {
31	  const legacyPolicy = LEGACY_OUTCOMES[outcome];
32	  const ceiling = legacyPolicy !== undefined ? 'pr' : outcome;
33	  const policy = automerge ?? legacyPolicy ?? 'nothing';
34	  if (!OUTCOMES.includes(ceiling)) {
35	    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
36	  }
37	  // Merging implies a PR exists; treat a merge as also having opened one so a
38	  // caller that only reports mergedPr is still judged correctly.
39	  const opened = openedPr || mergedPr;
40	
41	  if (ceiling === 'none' && opened) {
42	    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
43	  }
44	  if (ceiling === 'pr' && mergedPr) {
45	    const norm = normalizePolicy(policy);
46	    if (norm.kind === 'nothing' || norm.kind === 'invalid') {
47	      return { ok: false, violation: 'a task whose automerge authorizes nothing must not merge a pull request' };
48	    }
49	  }
50	  return { ok: true, violation: null };
51	}

